// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 ts1, uint256 value2, uint256 ts2) public {
        address actor = address(0xABCD);
        ts1 = bound(ts1, 1, type(uint256).max / 2);
        value2 = bound(value2, 0, 10 ether);
        vm.deal(actor, 10 ether);

        // A well-formed first call succeeds and legitimately sets pastBlockTime = ts1 + 1.
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");
        uint256 afterFirst = c.pastBlockTime();

        // Second call with fuzzed value/timestamp; keep timestamp admissible (no time jump past guard requirement is allowed).
        vm.assume(ts2 <= ts1 + 1);
        vm.warp(ts2);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: value2}("");

        // General rule: any REVERTING call must leave pastBlockTime unchanged.
        if (!ok2) {
            assertEq(c.pastBlockTime(), afterFirst, "reverted call must not change pastBlockTime");
        } else {
            assertTrue(true);
        }
    }
}
